//! The ADR 0132 threading ABI: how a Tier 2 block fun is recognised, and the
//! `Acc` a plain class-method entry hands its threaded body.
//!
//! **DDD Context:** Compilation — Code Generation
//!
//! Both cross the Rust/Erlang boundary, so neither is copied: this module is
//! the source, [`erlang_header`] renders it into the checked-in
//! `runtime/apps/beamtalk_runtime/include/beamtalk_threading_abi.hrl`
//! (regenerated by `beamtalk build-stdlib`, guarded by
//! `just check-generated-builtins` and by
//! `tests::checked_in_header_matches_the_generator`), and `beamtalk_dispatch.erl`
//! includes that header instead of spelling the atoms (the same pattern as
//! [`super::class_var_keys`]).
//!
//! # The Tier 2 mark (BT-3885)
//!
//! A Tier 2 block (ADR 0041) compiles to `fun (Args..., StateAcc) -> {Result,
//! StateAcc1}`, one argument more than the block's own. By arity alone it is
//! indistinguishable from a plain block that takes one argument more than it is
//! called with, so `beamtalk_dispatch:call_threaded/3` could only tell the two
//! apart *after* applying the fun (running a wrong-arity block's body with the
//! caller's `Acc` as an argument) and by the shape of its reply (accepting any
//! `{_, Map}`, such as an Erlang `{ok, #{...}}`, as a Tier 2 reply).
//!
//! Instead every Tier 2 block is minted as a `letrec`-bound fun named
//! [`TIER2_BLOCK_FUN_NAME`]:
//!
//! ```erlang
//! letrec 'BtTier2Block'/2 = fun (X, StateAcc) -> ... in 'BtTier2Block'/2
//! ```
//!
//! The Erlang compiler names the lifted function of a `letrec` fun
//! `-<Function>/<Arity>-<Name>/<Arity>-<N>-` (an anonymous fun is
//! `-<Function>/<Arity>-anonymous-<N>-`), so `erlang:fun_info(F, name)` carries
//! the mark on the fun value itself and the gate decides the tier *before*
//! applying anything. The `letrec` is not recursive and costs nothing at run
//! time: the closure is created by the same `make_fun` as an anonymous one.

use beamtalk_cerl_doc::{Document, docvec, leaf};

use super::util::metaclass_tag;

/// The `letrec` name every Tier 2 block fun is minted under. A valid Erlang
/// variable name, so Erlang code can mint one too (a named fun of this name,
/// as `beamtalk_tier2_test_block:mark/1` does), and never a name codegen
/// derives from a user identifier.
pub const TIER2_BLOCK_FUN_NAME: &str = "BtTier2Block";

/// First element of the `Acc` a plain entry (of a class method, or of a
/// value-type instance method) passes its threaded body (ADR 0132 §2 as
/// amended by the BT-3871 review): `{'plain', ClassTag, Selector}`. It is never
/// used as a map; `call_threaded/3` runs a Tier 1 block with it and refuses a
/// Tier 2 one *without running it*, naming the method the caller sent.
pub const PLAIN_ENTRY_TAG: &str = "plain";

/// `(letrec 'BtTier2Block'/<arity> = <fun_doc> in 'BtTier2Block'/<arity> -| [])`:
/// the Tier 2 block `fun_doc` (a `fun (Args..., StateAcc) -> ...` of `arity`
/// parameters, `StateAcc` included) as a marked fun value.
pub(super) fn tier2_block_fun_doc(fun_doc: Document<'static>, arity: usize) -> Document<'static> {
    // Parenthesised so the value is one expression wherever a fun can stand
    // (an `apply` head, a `let` right-hand side, a call argument). Core Erlang
    // only parenthesises an annotated expression, hence the empty annotation.
    docvec![
        "(letrec ",
        leaf::fname(TIER2_BLOCK_FUN_NAME, arity),
        " = ",
        fun_doc,
        " in ",
        leaf::fname(TIER2_BLOCK_FUN_NAME, arity),
        " -| [])",
    ]
}

/// `{'plain', ClassTag, '<selector>'}`: the `Acc` the plain entry of method
/// `selector` of `class_name` hands its threaded body. `ClassTag` is the
/// receiver's class as the refusal names it: `'<Class> class'` for a class
/// method (`class_side`), `'<Class>'` for a value-type instance method (ADR 0132
/// Phase 1d).
pub(super) fn plain_entry_acc_doc(
    class_name: &str,
    class_side: bool,
    selector: &str,
) -> Document<'static> {
    let class_tag = if class_side {
        metaclass_tag(class_name)
    } else {
        class_name.to_string()
    };
    docvec![
        "{",
        leaf::atom(PLAIN_ENTRY_TAG),
        ", ",
        leaf::atom(class_tag),
        ", ",
        leaf::atom(selector.to_string()),
        "}"
    ]
}

/// Content of `beamtalk_threading_abi.hrl`, generated from the constants above
/// so the Erlang runtime and codegen share one mark and one sentinel shape.
#[must_use]
pub fn erlang_header() -> String {
    format!(
        "%% AUTO-GENERATED by `beamtalk build-stdlib` from \
         crates/beamtalk-codegen/src/core_erlang/threading_abi.rs — do not edit manually.\n\
         %% Copyright 2026 James Casey\n\
         %% SPDX-License-Identifier: Apache-2.0\n\
         \n\
         %% The ADR 0132 threading ABI shared with codegen: the mark a Tier 2 block\n\
         %% fun carries, and the `Acc` a plain class-method entry hands its body.\n\
         %% Regenerate with `just build-stdlib`; `just check-generated-builtins` fails\n\
         %% when this file is stale.\n\
         \n\
         -ifndef(BEAMTALK_THREADING_ABI_HRL).\n\
         -define(BEAMTALK_THREADING_ABI_HRL, true).\n\
         \n\
         %% The `letrec` name every Tier 2 block fun is minted under; the compiler\n\
         %% names its lifted function `-F/A-{TIER2_BLOCK_FUN_NAME}/Arity-N-`, which\n\
         %% `erlang:fun_info(Fun, name)` answers (BT-3885).\n\
         %% Erlang code mints one as a named fun of that name that uses its name\n\
         %% (`fun {TIER2_BLOCK_FUN_NAME}(Args..., Acc) -> _ = {TIER2_BLOCK_FUN_NAME}, Body end`;\n\
         %% an unused name is dropped by the compiler).\n\
         -define(BT_TIER2_BLOCK_NAME, '{TIER2_BLOCK_FUN_NAME}').\n\
         \n\
         %% The `Acc` the plain entry of class method `Selector` of `ClassTag`\n\
         %% (`'Name class'`) hands its threaded body; never used as a map.\n\
         -define(BT_PLAIN_ENTRY_ACC(ClassTag, Selector), {{'{PLAIN_ENTRY_TAG}', ClassTag, Selector}}).\n\
         \n\
         -endif.\n"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tier2_block_fun_doc_binds_the_fun_under_the_mark() {
        assert_eq!(
            tier2_block_fun_doc(Document::Str("fun (X, StateAcc) -> X"), 2).to_pretty_string(),
            "(letrec 'BtTier2Block'/2 = fun (X, StateAcc) -> X in 'BtTier2Block'/2 -| [])"
        );
    }

    #[test]
    fn plain_entry_acc_doc_names_the_method() {
        assert_eq!(
            plain_entry_acc_doc("Twice", true, "twice:").to_pretty_string(),
            "{'plain', 'Twice class', 'twice:'}"
        );
        // A value-type instance method (ADR 0132 Phase 1d).
        assert_eq!(
            plain_entry_acc_doc("Twice", false, "twice:").to_pretty_string(),
            "{'plain', 'Twice', 'twice:'}"
        );
    }

    /// The checked-in header is exactly what `build-stdlib` regenerates, so the
    /// runtime's gate cannot drift from the mark codegen emits.
    #[test]
    fn checked_in_header_matches_the_generator() {
        assert_eq!(
            include_str!(
                "../../../../runtime/apps/beamtalk_runtime/include/beamtalk_threading_abi.hrl"
            ),
            erlang_header()
        );
    }

    #[test]
    fn header_defines_the_shared_shape() {
        let hrl = erlang_header();
        assert!(hrl.contains("-define(BT_TIER2_BLOCK_NAME, 'BtTier2Block')."));
        assert!(hrl.contains(
            "-define(BT_PLAIN_ENTRY_ACC(ClassTag, Selector), {'plain', ClassTag, Selector})."
        ));
    }
}
